import os
import pprint
import re
import subprocess
import sys
import traceback
import requests
from taf.internal.wireshark.installation.py3_string import py3_string

ENABLE_WS_SPECIFIC_PLUGIN_COMPARISION = False
DEFAULT_ARTIFACTORY = 'https://artifactory-hz1.int.net.nokia.com/artifactory'
REMOTE_PLUGIN_FOLDER_NAME = 'wslte5g_plugins-local'
TOOLS_FOLDER_NAME = 'tools'
SCRIPT_NAME = 'install_wslte_plugins.bash'
SCRIPT_URL = '{}/{}/{}/{}'.format(DEFAULT_ARTIFACTORY, REMOTE_PLUGIN_FOLDER_NAME, TOOLS_FOLDER_NAME, SCRIPT_NAME)
MAIN_PLUGIN_URL = '{}/{}'.format(DEFAULT_ARTIFACTORY, REMOTE_PLUGIN_FOLDER_NAME)
SCRIPT_TARGET_DIR = '/home/ute'
UTE_TOKEN_DIR = '/etc/token/ca_ute_artifactory_readonly'
UTE_TOKEN = None
NOT_IMPLEMENTED_TSHARK_PLUGINS = ['xnap', 'f1ap']
AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION = {
    'nsetap': {'plugin_name': 'nsetap',
               'script_switch': '--nsetap',
               'artifactory_folder_name': 'NSETAP',
               'artifactory_plugin_name_prefix': 'nsetap',
               'ws_version_regexp': None},
    'nsetapx': {'plugin_name': 'nsetapx',
                'script_switch': '--nsetapx',
                'artifactory_folder_name': 'NSETAP_X',
                'artifactory_plugin_name_prefix': 'nsetapx',
                'ws_version_regexp': re.compile(r'^\d+\.\d+\.\d-\d+(?:\.\d+)*')},
    'xnap': {'plugin_name': 'nokiaxnap',
             'script_switch': '--nokiaxn',
             'artifactory_folder_name': 'Nokia_Xn_AP',
             'artifactory_plugin_name_prefix': 'nokiaf1ap',
             'ws_version_regexp': None},
    'f1ap': {'plugin_name': 'nokiaf1ap',
             'script_switch': '--nokiaf1',
             'artifactory_folder_name': 'Nokia_F1_AP',
             'artifactory_plugin_name_prefix': 'nokiaxnap',
             'ws_version_regexp': None},
}
AGENT_BUILD_PATH = '/home/ute/.ute-ca/cache/bts/'


class PluginInstallationFailed(Exception):
    pass


def get_build():
    agent_dowloaded_build_dir = os.listdir(AGENT_BUILD_PATH)
    for build in agent_dowloaded_build_dir:
        if 'SBTS' in build:
            return build
    raise Exception('Could not get build from path: {}, found builds: {} '
                    .format(AGENT_BUILD_PATH, agent_dowloaded_build_dir))


def download_dissector_installation_script(target_dir=SCRIPT_TARGET_DIR, re_download=False):
    target_file = os.path.sep.join([target_dir, SCRIPT_NAME])
    if os.path.exists(target_file):
        if re_download is True:
            print('Removing previous script version from: {}'.format(target_file))
            os.remove(target_file)
        else:
            print('Script already downloaded at: {}'.format(target_file))
            return target_file
    script_and_params = ['wget', SCRIPT_URL]
    token = _get_ute_token()
    if token:
        print('Using ca_ute_artifactory_readonly for artifactory access for download')
        script_and_params.append('--header')
        script_and_params.append("Authorization: Bearer {}".format(token))
    stdout, stderr = subprocess.Popen(script_and_params,
                                      cwd=target_dir,
                                      stdout=subprocess.PIPE,
                                      stderr=subprocess.PIPE).communicate()
    print('Wget output: {}'.format(pprint.pformat(py3_string(stdout))))
    if stderr:
        print('Wget Error: {}'.format(pprint.pformat(py3_string(stdout))))
    print('Successfully downloaded script to: {}'.format(target_file))
    subprocess.Popen(['chmod', '+x', target_file]).communicate()
    print('Added executable rights for script: {}'.format(target_file))
    return target_file


def get_installed_tshark_plugins(log_output=False):
    stdout, stderr = subprocess.Popen(['tshark', '-G', 'plugins'], stdout=subprocess.PIPE).communicate()
    lines = py3_string(stdout).split("\n")
    elements = [[y.strip() for y in x.split('\t')] for x in lines if x]
    plugin_list = [dict(zip(('name', 'version', 'type', 'path'), item)) for item in elements]
    if log_output:
        print(pprint.pformat(plugin_list))
    return plugin_list


def get_tshark_plugin(name):
    plugins = get_installed_tshark_plugins()
    regexp_string = r"^{}\W".format(name)
    plug_regexp = re.compile(regexp_string)
    matching_plugins = []
    for plug in plugins:
        if plug_regexp.search(plug['name']):
            matching_plugins.append(plug)
    if len(matching_plugins):
        assert len(matching_plugins) == 1, 'Have {} plugins: {} matching name: {}'\
            .format(len(matching_plugins), [n['name'] for n in matching_plugins], name)
        print('Found plugins: {} with attributes:\n{}'.format(matching_plugins[0]['name'],
                                                              pprint.pformat(matching_plugins[0])))
        return matching_plugins[0]
    else:
        print('Not found any plugins matching: {}'.format(name))
        return None


def _get_ute_token():
    """
    Return required read-only token to access artifactory
    :return:
    """
    global UTE_TOKEN
    if UTE_TOKEN is not None:
        return UTE_TOKEN
    if os.path.exists(UTE_TOKEN_DIR):
        with open(UTE_TOKEN_DIR, 'r') as token_file:
            token = token_file.read().strip()
        if token:
            UTE_TOKEN = token
            return token
    return None


def _get_url_content(url, raw=False):
    token = _get_ute_token()
    request_param = {'url': url}
    if token:
        print('Using ca_ute_artifactory_readonly for artifactory access')
        request_param['headers'] = {'Authorization': 'Bearer {}'.format(token)}
    response = requests.get(**request_param)
    content = response.content
    if raw is False:
        if sys.version_info[0] >= 3:
            content = content.decode(errors='replace')
        return requests.utils.unquote(content)
    else:
        return content


def get_latest_plugin_version_from_artifactory(plugin):
    """
    All possible version are read from folder names inside the selected plugin folder, e.g.
    https://artifactory-hz1.int.net.nokia.com/artifactory/wslte5g_plugins-local/NSETAP_X/
    Will always return only major version, no knowledge about existing internal versions
    :param plugin:
    :return:
    """
    content = _get_url_content("/".join([MAIN_PLUGIN_URL,
                                         AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin]['artifactory_folder_name']])
                               )
    plugins = (re.findall(r'(?<=<a href="{}-)[^"\/]*'
                          .format(AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin]['plugin_name']), content))
    try:
        plugins.sort(key=_sort_by_version)
    except Exception as e:
        print('Sorting by 4 leftmost groups of digits failed with exception:\n{}\non list:\n{}'
              '\nFalling back to string-based sorting'.format(e, pprint.pformat(plugins)))
        plugins.sort()
    latest_plugin_version = plugins[-1]
    print('Found latest version: {} for plugin: {}'.format(latest_plugin_version, plugin))
    return latest_plugin_version


def _sort_by_version(elem):
    """
    Take all possible numbers, catenate them as string and cast to int.
    :param elem:
    :return:
    """
    max_number_of_versions = 4  # some old f1/xn plugins does not comply with latest convention
    all_version_numbers = re.findall(r'\d+', elem)
    all_allowed_version_numbers = all_version_numbers[0:max_number_of_versions]
    return int("".join(all_allowed_version_numbers))


def get_latest_plugin_wireshark_specific_version_from_artifactory(plugin, major_version):
    artifactory_folder = AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin]['artifactory_folder_name']
    artifactory_name = AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin]['plugin_name']
    name_with_version = "{}-{}".format(artifactory_name, major_version)
    content = _get_url_content("/".join([MAIN_PLUGIN_URL, artifactory_folder, name_with_version]))
    all_plugins = sorted(set(re.findall(r'\<a href\=\"{}-\d+.\d+-(.*?)\+'.format(artifactory_name), content)), reverse=True)
    print('For: {} found plugins:\n{}'.format("{}-{}".
                                              format(artifactory_name, major_version),
                                              pprint.pformat(all_plugins)))
    latest_plugin_version = all_plugins[0]
    print('Found latest version: {} for plugin: {}'.format(latest_plugin_version, plugin))
    return latest_plugin_version


def _compare_plugin_ws_specific_versions(plugin_name, installed_version, requested_version):
    if ENABLE_WS_SPECIFIC_PLUGIN_COMPARISION is False:
        return False
    try:
        ws_specific_regex = AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin_name]['ws_version_regexp']
        if ws_specific_regex is not None and ws_specific_regex.search(installed_version):
            print('Plugin for: {} installed with WS specific version: {}'.format(plugin_name, installed_version))
            try:
                latest_ws_specific_version = \
                    get_latest_plugin_wireshark_specific_version_from_artifactory(plugin_name, requested_version)
            except Exception as e:
                print('Could not get latest WS specific version for: {}-{} due to: {}'
                      .format(plugin_name, requested_version, e))
                latest_ws_specific_version = None
            if latest_ws_specific_version is not None and latest_ws_specific_version == installed_version:
                return True
        return False
    except Exception as e2:
        print('Failed to compare ws_specific versions due to: {}'.format(e2))
        traceback.print_exc()
        return False


def install_plugin(plugin_name, version='latest', force=False):
    assert plugin_name in AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION.keys(), \
        'Requested plugin: {} cannot be installed via wireshark download script.' \
        ' Only available plugins: {}'.format(plugin_name, list(AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION.keys()))
    assert plugin_name not in NOT_IMPLEMENTED_TSHARK_PLUGINS,\
        'Plugin: {} not yet implemented by wireshark'.format(plugin_name)
    installed_plugin = get_tshark_plugin(plugin_name)
    if version == 'latest':
        version = get_latest_plugin_version_from_artifactory(plugin_name)
    if installed_plugin is not None:
        if force is True:
            print('Forcing installation of plugin: {}\nRemoving: {}'
                  .format(plugin_name, installed_plugin['path']))
            os.remove(installed_plugin['path'])
        else:
            if installed_plugin['version'] == version:
                print('Plugin: {} already installed with version : {}'.format(plugin_name, version))
                return installed_plugin['version']
            elif _compare_plugin_ws_specific_versions(plugin_name, installed_version=installed_plugin['version'],
                                                      requested_version=version) is True:
                print('WS specific plugin: {} already installed with latest version : {}'.format(plugin_name, version))
                return installed_plugin['version']
            else:
                print('Plugin installed with other version: {}, removing'.format(installed_plugin['version']))
                os.remove(installed_plugin['path'])
    installation_script = download_dissector_installation_script(re_download=False)

    stdout, stderr = subprocess.Popen([installation_script,
                                       AVAILABLE_SCRIPT_PLUGINS_TO_SCRIPT_OPTION[plugin_name]['script_switch'],
                                       version],
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
    print('Script output: {}'.format(pprint.pformat(py3_string(stdout))))
    if stderr:
        print('Script Error: {}'.format(pprint.pformat(py3_string(stdout))))
    tshark_plugin_after_script_run = get_tshark_plugin(plugin_name)
    if tshark_plugin_after_script_run is None or (version not in tshark_plugin_after_script_run['version']):
        raise PluginInstallationFailed('Cannot install plugin: {} with version: {}'.format(plugin_name, version))
    return version


def install_mcshark(build=None, force=False):
    if build is None:
        build = get_build()
    installation_script = download_dissector_installation_script(re_download=False)
    installed_plugin = get_tshark_plugin('mcshark')
    if installed_plugin is not None:
        if force is True:
            print('Forcing installation of mcshark for: {}\nRemoving: {}'.format(build, installed_plugin['name']))
            os.remove(installed_plugin['path'])
        else:
            if build in installed_plugin['name']:
                print('Plugin: {} already installed with version : {}'.format('mcshark', installed_plugin['name']))
                return
            else:
                print('Plugin installed with other version: {}, removing'.format(installed_plugin['name']))
                os.remove(installed_plugin['path'])
    stdout, stderr = subprocess.Popen([installation_script,
                                       '--sbts',
                                       build],
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
    print('Script output: {}'.format(pprint.pformat(py3_string(stdout))))
    if stderr:
        print('Script Error: {}'.format(pprint.pformat(py3_string(stdout))))
    installed_plugin = get_tshark_plugin('mcshark')
    if installed_plugin is None or (build not in installed_plugin['name']):
        raise PluginInstallationFailed('Cannot install plugin: {} with version: {}'.format('mcshark', build))
    return installed_plugin['name']
